					Long deviceid = (crashEntity.getDeviceConsent() == AppticsConstants.ANON_DEVICEID ) ? crashEntity.getDeviceID() :  MaskHandler.getDeviceMaskIDFromCassandra(crashEntity.getDeviceID(),appID);
					SimpleDateFormat sf = new SimpleDateFormat("yyyy-MM-dd");
					String zsoid = DataspaceAndAppMapper.getInstance().getOrgLoginname(crashEntity.getProjectID());

					crashurl = AppticsConstants.SERVICEURL+"/ac/"+zsoid+"/"+appID+"/exception/"+crashEntity.getExceptionGroup()+"?startDate="+sf.format(new Date())+"&endDate="+sf.format(new Date())+"&exceptionGroup="+crashEntity.getExceptionGroup()+"&mode="+crashEntity.getMode()+"&dateRangeIndex=11&deviceID="+deviceid+"&happenedAt="+crashEntity.getHappenedAt();
					LOGGER.log(Level.INFO,"url is {0}",crashurl);
				}

				if(crashEntity.getBrand().equalsIgnoreCase(AppticsConstants.APPLE)) {
					crashEntity.setMsgContent(issueName);
				}
				else {
					crashEntity.setMsgContent(message);
				}

				String mailCont = crashEntity.getMailContent();
				mailCont = mailCont.replaceAll("\\n", "<br>");
				mailCont = mailCont.replaceAll("\\t", "&nbsp;&nbsp;&nbsp;&nbsp;");

				LOGGER.log(Level.INFO, "Mail content -- {0}", mailCont);
				String cliqsubtype = "all";
				String appAndBuildversion = crashEntity.getAppVersion() + "("+crashEntity.getAppReleaseVersion()+")";

				String subject = "Crash " + EmailNotificationContent.MODES.get(mode) + " | " + displayName + " " + appAndBuildversion + " | " + crashEntity.getPlatform() + " " + crashEntity.getOsVersion() + " | " + issueName;
				LOGGER.log(Level.INFO, "Mail subject -- {0}", subject);

				String zsoid = DataspaceAndAppMapper.getInstance().getOrgLoginname(appID);

				LOGGER.log(Level.INFO, "----Before sendtoasana method----");
				sendToAsana(zsoid, bundleId, crashurl, message + "- Asana - " + System.currentTimeMillis(), subject);

				if(crashEntity.getIsNewUniqueID()){

					cliqsubtype = "unique";

					sendCrashMail(crashEntity, appAndBuildversion, subject, true, module, crashurl, displayName);
					String bugDescription = crashurl+"\n\n"+message;
					if(issueName.contains("unsymbolicated") || issueName.contains("Missing Symbols")) 
					{
						LOGGER.log(Level.INFO, "Skiping unsymbolicated and Missing Symbols crash to assign in projects for {0},{1},{2},{3},{4},{5}", new Object[] { bundleId, issueName, bugDescription, uniqueId, appID, crashEntity.getAppVersionID()});
					}
					else
					{
						String bugTitle = displayName+" "+ appAndBuildversion+" | "+crashEntity.getPlatform()+" "+crashEntity.getOsVersion()+" | "+issueName;
						Integrations.PROJECT.addCrashAsBug(module, "unique", bundleId, bugTitle, bugDescription, uniqueId, appID, crashEntity.getAppVersionID());

						// String zsoid = DataspaceAndAppMapper.getInstance().getOrgLoginname(appID);
                        Integrations.JIRA.sendToJira(
