		private static void sendToAsana(String zsoid, long bundleId, String crashurl, String message, String bugTitle) {
			try {
				LOGGER.log(Level.INFO, "Inside the send to asana method");
				Long zuID = AppticsIAMUtil.getCurrentUserZUID();

				if (zuID != null) {
					AsanaHandler asanaHandler = new AsanaHandler();
					JSONObject asanaConfig = asanaHandler.getConfiguration(bundleId);
					LOGGER.log(Level.INFO, "ASANA GETCONF  {0}", asanaConfig);

					if (asanaConfig != null) {
						JSONObject configuration = asanaConfig.optJSONObject("Configuration"); // get nested object

						if (configuration != null) {
							String workspaceGid = configuration.optString("workspaceGid", null);
							String projectGid = configuration.optString("projectGid", null);

							LOGGER.log(Level.INFO, "ASANA workspaceGid {0}", workspaceGid);
							LOGGER.log(Level.INFO, "ASANA projectGid {0}", projectGid);

							if (!CommonUtil.isEmpty(workspaceGid, projectGid)) {
								String taskDescription = crashurl + "\n\n" + message; // no i18N

								JSONObject asanaResult = asanaHandler.addAsanaTask(zuID, workspaceGid, projectGid, bugTitle, taskDescription, null, zsoid, bundleId);
								LOGGER.log(Level.INFO, "Asana task creation result: {0}", asanaResult);
							}
						} else {
							LOGGER.log(Level.WARNING, "Asana configuration object is null for bundleId: {0}", bundleId);
						}
					} else {
						LOGGER.log(Level.WARNING, "Asana config not found for bundleId: {0}", bundleId);
					}
				} else {
					LOGGER.log(Level.WARNING, "Asana zuID not found for zsoid: {0}", zsoid);
				}
			} catch (Exception e) {
				LOGGER.log(Level.SEVERE, "Exception while creating Asana task for crash", e);
			}
		}

