private JSONObject getCliqIntegrationDetailByApid(String moduleName, String subType, Long apID)
{
	JSONObject configuration = IntegrationHandler.getIntegrationDetails(AppticsConstants.NEWCLIQINTEGRATIONS, moduleName, subType, apID);

	if(CommonUtil.isEmpty(configuration))
	{
		LOGGER.log(Level.INFO, "Getting configuration as empty.");
		return null;
	}

	try
	{
		Long zuid = configuration.getLong("zuid");
		if(CommonUtil.isEmpty(zuid))
		{
			LOGGER.log(Level.INFO, "Getting zuid as empty.");
			return null;
		}

		String accessToken = getCliqUserAccessToken(zuid, null);
		if(CommonUtil.isEmpty(accessToken))
		{
			LOGGER.log(Level.INFO, "Getting access token as empty.");
			return null;
		}

		JSONObject cliqDetails = new JSONObject();
		cliqDetails.put("chatID", configuration.getString("channelid"));
		cliqDetails.put("chatName", configuration.has("channalname") ? configuration.getString("channalname") : "");
		cliqDetails.put("accessToken", accessToken);

		return cliqDetails;
	}
	catch(JSONException e)
	{
		LOGGER.log(Level.SEVERE, "Exception getting integration details for cliq", e);
	}
	return null;
}

