package com.zoho.apptics.integration;

import com.adventnet.ds.query.*;
import com.adventnet.persistence.Row;
import com.zoho.apptics.util.*;
import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;

import java.util.*;
import java.util.logging.Level;
import java.util.logging.Logger;

public class JiraHandler {

    private static final Logger LOGGER = Logger.getLogger(JiraHandler.class.getName());
    private final String JIRA_BASE_URL = "https://api.atlassian.com";
    private final String JIRA_SCOPE = "write:jira-work";


    @FunctionalInterface
    private interface JiraCall<T> {
        T execute(String token);
    }

    public record JiraSites(
            String cloudId,
            String name
    ) {
        public JSONObject toJson() {
            JSONObject json = new JSONObject();
            json.put("name", name);
            json.put("cloud_id", cloudId);
            return json;
        }

        @Override
        public String toString() {
            return toJson().toString();
        }
    }

    record JiraAuth(
            String zsoId,
            long projectId,
            String accessToken,
            String refreshToken
    ) { }

    public record JiraProject(
            String projectName,
            String projectKey,
            String projectId
    ) {
        public JSONObject toJson() {
            JSONObject json = new JSONObject();
            json.put("project_name", projectName);
            json.put("project_key", projectKey);
            json.put("project_id", projectId);
            return json;
        }

        @Override
        public String toString() {
            return toJson().toString();
        }
    }

    public record JiraIssueType(
            String name,
            String id
    ) {
        public JSONObject toJson() {
            JSONObject json = new JSONObject();
            json.put("issue_type_name", name);
            json.put("issue_type_id", id);
            return json;
        };

        @Override
        public String toString() {
            return toJson().toString();
        }
    }


    private JSONObject makeJiraConnection(JiraAuth auth, JiraCall<JSONObject> jiraCall) {
        JSONObject callResponse = jiraCall.execute(auth.accessToken);
        if (callResponse.has("code") && callResponse.getInt("code") == 401) {
            String refreshedToken = refreshToken(auth);
            if (refreshedToken != null) {
                callResponse = jiraCall.execute(refreshedToken);
            }
        }
        return callResponse;
    }

    private synchronized String refreshToken(JiraAuth auth) {
        try {
            String jiraCID = PropertyHandler.getValue(AppticsConstants.JIRA_CLIENT_ID);
            String jiraClientSecret = PropertyHandler.getValue(AppticsConstants.JIRA_CLIENT_SECRET);

            if (CommonUtil.isEmpty(jiraCID, jiraClientSecret)) {
                LOGGER.log(Level.INFO, "Invalid Jira client id or client secret");
                return null;
            }

            String tokenExchangeUrl = JIRA_BASE_URL + "/oauth/token";

            JSONObject requestBody = new JSONObject();
            requestBody.put("grant_type", "refresh_token");
            requestBody.put("client_id", jiraCID);
            requestBody.put("client_secret", jiraClientSecret);
            requestBody.put("refresh_token", auth.refreshToken);

            String tokenExchangeResponse = new HttpURLConnectionInvoker(true)
                    .invokePostHttpURLConnWithRequestBody(
                            tokenExchangeUrl,
                            null, null,
                            requestBody
                    );

            JSONObject authExchangeJSONResponse = new JSONObject(tokenExchangeResponse);

            String jiraRefreshToken = authExchangeJSONResponse.optString("refresh_token", null);
            String jiraAccessToken = authExchangeJSONResponse.optString("access_token", null);
            String jiraAccessExpiry = authExchangeJSONResponse.optString("expires_in", null);
            String jiraScope = authExchangeJSONResponse.optString("scope", null);

            if (CommonUtil.isEmpty(jiraRefreshToken, jiraAccessToken, jiraAccessExpiry, jiraScope)) {
                return null;
            }

            addOrUpdateJiraAuth(auth.projectId, auth.zsoId, jiraAccessToken, jiraRefreshToken);
            return jiraAccessToken;

        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Exception while Jira token rotation", e);
        }
        return null;
    }

    public boolean authenticate(
            String code,
            String redirectUri,
            String zsoId,
            long projectId
    ) {
        String authExchangeUrl = JIRA_BASE_URL + "/oauth/token";

        String jiraCID = PropertyHandler.getValue(AppticsConstants.JIRA_CLIENT_ID);
        String jiraClientSecret = PropertyHandler.getValue(AppticsConstants.JIRA_CLIENT_SECRET);

        if (CommonUtil.isEmpty(jiraCID, jiraClientSecret)) {
            LOGGER.log(Level.INFO, "Invalid Jira client id or client secret");
            return false;
        }

        try {
            JSONObject requestBody = new JSONObject();
            requestBody.put("code", code);
            requestBody.put("redirect_uri", redirectUri);
            requestBody.put("grant_type", "authorization_code");
            requestBody.put("client_id", jiraCID);
            requestBody.put("client_secret", jiraClientSecret);

            String authExchangeResponse = new HttpURLConnectionInvoker(true).invokePostHttpURLConnWithRequestBody(
                    authExchangeUrl,
                    null,
                    null,
                    requestBody
            );
            LOGGER.log(Level.INFO, authExchangeResponse);
            JSONObject authExchangeJSONResponse = new JSONObject(authExchangeResponse);

            String jiraRefreshToken = authExchangeJSONResponse.optString("refresh_token", null);
            String jiraAccessToken = authExchangeJSONResponse.optString("access_token", null);
            String jiraAccessExpiry = authExchangeJSONResponse.optString("expires_in", null);
            String jiraScope = authExchangeJSONResponse.optString("scope", null);

            if (CommonUtil.isEmpty(jiraRefreshToken, jiraAccessToken, jiraAccessExpiry, jiraScope)) {
                return false;
            }
            addOrUpdateJiraAuth(projectId, zsoId, jiraAccessToken, jiraRefreshToken);

            return true;
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Exception while authenticating Jira", e);
        }
        return false;
    }

    public List<JiraSites> getJiraSites(String zsoId, Long projectId) {
        try {
            JiraAuth jiraAuth = getJiraAuth(zsoId, projectId);
            if (jiraAuth == null) {
                return null;
            }

            JSONObject jiraResponse = makeJiraConnection(jiraAuth, (String token) -> {
                if (CommonUtil.isEmpty(token)) {
                    return null;
                }
                String accessibleResourcesUrl = JIRA_BASE_URL + "/oauth/token/accessible-resources";

                Map<String, String> headers = new HashMap<>();
                headers.put("Authorization", "Bearer " + token);
                headers.put("Accept", "application/json");
                LOGGER.log(Level.INFO , "Token {0}", token);
                try {
                    String accessibleResourcesResponse = new HttpURLConnectionInvoker(true)
                            .invokeGetHttpURLConn(
                                    accessibleResourcesUrl,
                                    headers,
                                    null
                            );
                    return new JSONObject(accessibleResourcesResponse);
                } catch (Exception e) {
                    LOGGER.log(Level.SEVERE, "Exception while fetching Jira Projects", e);
                }
                return null;
            });

            if (jiraResponse == null) {
                return null;
            }

            ArrayList<JiraSites> sites = new ArrayList<>();

            JSONArray resourcesArray = jiraResponse.getJSONArray("data");
            for (int i = 0; i < resourcesArray.length(); i++) {
                JSONObject resource = resourcesArray.getJSONObject(i);
                JiraSites site = new JiraSites(
                        resource.getString("id"),
                        resource.getString("name")
                );
                sites.add(site);
            }

            return sites;

        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Exception while fetching Jira sites", e);
        }
        return null;
    }

    public List<JiraProject> getJiraProjects(String zsoId, Long projectId, String cloudId) {
        try {
            JiraAuth jiraAuth = getJiraAuth(zsoId, projectId);
            if (jiraAuth == null) {
                return null;
            }
            JSONObject jiraResponse = makeJiraConnection(jiraAuth, (String token) -> {
                if (CommonUtil.isEmpty(token, cloudId)) {
                    return null;
                }
                String getProjectsUrl = JIRA_BASE_URL + "/ex/jira/" + cloudId + "/rest/api/3/project/search";
                Map<String, String> params = new HashMap<>();
                params.put("status", "live");
                params.put("maxResults", "100");

                Map<String, String> headers = new HashMap<>();
                headers.put("Authorization", "Bearer " + token);
                LOGGER.log(Level.INFO , "Token {0}", token);
                try {
                    String jiraProjectsResponse = new HttpURLConnectionInvoker(true)
                            .invokeGetHttpURLConn(
                                    getProjectsUrl,
                                    headers,
                                    params
                            );
                    return new JSONObject(jiraProjectsResponse);
                } catch (Exception e) {
                    LOGGER.log(Level.SEVERE, "Exception while fetching Jira Projects", e);
                }
                return null;
            });

            if (jiraResponse == null) {
                return null;
            }

            ArrayList<JiraProject> jiraProjects = new ArrayList<>();
            JSONArray jiraProjectsJSONArray = jiraResponse.optJSONArray("values", null);
            if (jiraProjectsJSONArray == null) {
                return null;
            }

            for (int i = 0; i < jiraProjectsJSONArray.length(); i++) {
                JiraProject project = new JiraProject(
                        jiraProjectsJSONArray.getJSONObject(i).getString("name"),
                        jiraProjectsJSONArray.getJSONObject(i).getString("key"),
                        jiraProjectsJSONArray.getJSONObject(i).getString("id")
                );
                jiraProjects.add(project);
            }

            return jiraProjects;

        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Exception while getting Jira projects list", e);
        }

        return null;
    }

    public List<JiraIssueType> getJiraIssueTypes(
            String zsoId,
            long projectId,
            String cloudId,
            String jiraProjectId
    ) {
        JiraAuth jiraAuth = getJiraAuth(zsoId, projectId);
        if (jiraAuth == null) {
            return null;
        }

        JSONObject jiraResponse = makeJiraConnection(jiraAuth, (String token) -> {
            if (CommonUtil.isEmpty(token, cloudId)) {
                return null;
            }

            String getIssueTypesUrl = JIRA_BASE_URL
                    + "/ex/jira/" + cloudId
                    + "/rest/api/3/issue/createmeta/"
                    + jiraProjectId
                    + "/issuetypes";

            Map<String, String> params = new HashMap<>();
            params.put("maxResults", "100");

            Map<String, String> headers = new HashMap<>();
            headers.put("Authorization", "Bearer " + token);

            try {
                String jiraProjectsResponse = new HttpURLConnectionInvoker(true)
                        .invokeGetHttpURLConn(
                                getIssueTypesUrl,
                                headers,
                                params
                        );
                return new JSONObject(jiraProjectsResponse);
            } catch (Exception e) {
                LOGGER.log(Level.SEVERE, "Exception while fetching Jira issue types", e);
            }
            return null;
        });

        if (jiraResponse == null) {
            return null;
        }

        ArrayList<JiraIssueType> issueTypes = new ArrayList<>();
        JSONArray issueTypesJSONArray = jiraResponse.optJSONArray("issueTypes");
        if (issueTypesJSONArray == null) {
            return null;
        }

        for (int i = 0; i < issueTypesJSONArray.length(); i++) {
            int hierarchyLevel = issueTypesJSONArray.getJSONObject(i).getInt("hierarchyLevel");
            if (hierarchyLevel == 0) {
                JiraIssueType issueType = new JiraIssueType(
                        issueTypesJSONArray.getJSONObject(i).getString("name"),
                        issueTypesJSONArray.getJSONObject(i).getString("id")
                );
                issueTypes.add(issueType);
            }
        }

        return issueTypes;
    }

    /*
     * No need for app and role validation, since it is an internal call.
     */
    public boolean sendToJira(
            String zsoId,
            long projectId,
            long apId,
            String moduleName,
            String issueTitle,
            String issueDescription,
            String crashLink
    ) {
        try {
            JiraAuth jiraAuth = getJiraAuth(zsoId, projectId);
            if (jiraAuth == null) {
                LOGGER.log(Level.INFO, "Jira Auth is null");
                return false;
            }

            JSONObject configuration = IntegrationHandler.getIntegrationDetailsByService(
                    AppticsConstants.JIRA,
                    moduleName,
                    "unique",
                    apId
            );
            if (configuration == null) {
                LOGGER.log(Level.INFO, "Jira Config is null");
                return false;
            }

            LOGGER.log(Level.INFO, "Jira Config {0}", configuration.toString());

            String jiraCloudId = configuration.getString("cloud_id");
            String jiraProjectId = configuration.getString("project_id");
            String jiraIssueTypeId = configuration.getString("issue_type_id");

            if (CommonUtil.isEmpty(jiraProjectId, jiraIssueTypeId)) {
                return false;
            }

            JSONObject jiraResponse = makeJiraConnection(jiraAuth, (String token) -> {
                if (CommonUtil.isEmpty(token, jiraCloudId)) {
                    return null;
                }

                String addIssueUrl = JIRA_BASE_URL
                        + "/ex/jira/" + jiraCloudId
                        + "/rest/api/3/issue";

                Map<String, String> headers = new HashMap<>();
                headers.put("Authorization", "Bearer " + token);

                String createIssueResponse = new HttpURLConnectionInvoker(true)
                        .invokePostHttpURLConnWithRequestBody(
                                addIssueUrl,
                                headers,
                                null,
                                buildRequestBodyToCreateIssue(jiraProjectId, jiraIssueTypeId, issueTitle, issueDescription, crashLink)
                        );
                return new JSONObject(createIssueResponse);
            });

            if (jiraResponse.has("id")) {
                return true;
            }

        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Exception while sending unique crash to Jira", e);
        }
        return false;
    }

    public void updateConfiguration(
            long apId,
            JSONObject configuration
    ) throws Exception {

        new IntegrationHandler().checkAndAddConfiguration(
                AppticsConstants.JIRA,
                apId,
                configuration
        );
    }

    public JSONObject getConfiguration(
            long apId
    ) throws Exception {
        return IntegrationHandler.getConfiguration(apId, AppticsConstants.JIRA);
    }

    private String getCloudIdFromAccessibleResources(JSONObject accessibleResources) throws JSONException {
        JSONArray resourcesArray = accessibleResources.getJSONArray("data");

        for (int i = 0; i < resourcesArray.length(); i++) {
            JSONObject resource = resourcesArray.getJSONObject(i);
            JSONArray scopes = resource.getJSONArray("scopes");
            for (int j = 0; j < scopes.length(); j++) {
                if (scopes.getString(j).equals(JIRA_SCOPE)) {
                    return resource.getString("id");
                }
            }
        }
        return null;
    }

    private JSONObject buildRequestBodyToCreateIssue(
            String jiraProject,
            String jiraIssueType,
            String issueTitle,
            String issueDescription,
            String issueLink
    ) {
        JSONObject requestBody = new JSONObject();
        JSONObject fields = new JSONObject();

        JSONObject projectField = new JSONObject();
        projectField.put("id", jiraProject);

        JSONObject issueTypeField = new JSONObject();
        issueTypeField.put("id", jiraIssueType);

        JSONObject issueDescField = new JSONObject();
        issueDescField.put("type", "doc");
        issueDescField.put("version", 1);

        JSONArray contentArr = new JSONArray();

        // Paragraph 1
        JSONObject p1 = new JSONObject();
        p1.put("type", "paragraph");

        JSONArray p1Content = new JSONArray();
        p1.put("content", p1Content);

        JSONObject linkText = new JSONObject();
        linkText.put("type", "text");
        linkText.put("text", issueLink);

        JSONArray marks = new JSONArray();
        JSONObject mark = new JSONObject();
        mark.put("type", "link");

        JSONObject attrs = new JSONObject();
        attrs.put("href", issueLink);

        mark.put("attrs", attrs);
        marks.put(mark);

        linkText.put("marks", marks);
        p1Content.put(linkText);

        // Add space text
        JSONObject spaceText = new JSONObject();
        spaceText.put("type", "text");
        spaceText.put("text", "  ");
        p1Content.put(spaceText);

        contentArr.put(p1);

        // Paragraph 2
        JSONObject p2 = new JSONObject();
        p2.put("type", "paragraph");

        JSONArray p2Content = new JSONArray();
        p2.put("content", p2Content);

        JSONObject stackText = new JSONObject();
        stackText.put("type", "text");
        stackText.put("text", issueDescription);

        p2Content.put(stackText);
        contentArr.put(p2);

        issueDescField.put("content", contentArr);

        fields.put("project", projectField);
        fields.put("issuetype", issueTypeField);
        fields.put("summary", issueTitle);
        fields.put("description", issueDescField);

        requestBody.put("fields", fields);

        return requestBody;
    }

    private JiraAuth getJiraAuth(
            String zsoId,
            long projectId
    ) {
        try {
            Criteria selectCriteria = new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.SERVICENAME), AppticsConstants.JIRA, QueryConstants.EQUAL);
            selectCriteria = selectCriteria.and(
                    new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ZUID), projectId, QueryConstants.EQUAL)
            );

            Row jiraAuthRow = DBHandler.getFirstRowFromRedis(AppticsConstants.REFRESHTOKEN, selectCriteria, zsoId);
            if (jiraAuthRow != null) {
                return new JiraAuth(
                        zsoId,
                        projectId,
                        jiraAuthRow.getAs(AppticsConstants.ACCESSTOKEN, String.class),
                        jiraAuthRow.getAs(AppticsConstants.REFRESHTOKEN, String.class)
                );
            }
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Exception while fetch cloud id for project", e);
        }
        return null;
    }

    private void addOrUpdateJiraAuth(
            long projectId,
            String zsoId,
            String accessToken,
            String refreshToken
    ) throws Exception {
        Map<String, Object> criteriaCols = new HashMap<>();
        criteriaCols.put(AppticsConstants.ZUID, projectId);
        criteriaCols.put(AppticsConstants.SERVICENAME, AppticsConstants.JIRA);
        if (MickeyUtil.isRowExist(
                AppticsConstants.REFRESHTOKEN,
                AppticsConstants.REFRESHTOKENID,
                criteriaCols,
                zsoId
        )) {
            LOGGER.log(Level.INFO, "Jira auth available for project already. Updating configs");

            Criteria updateCriteria = new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.SERVICENAME), AppticsConstants.JIRA, QueryConstants.EQUAL);
            updateCriteria = updateCriteria.and(
                    new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ZUID), projectId, QueryConstants.EQUAL)
            );

            Map<String, Object> updateColWithValue = new HashMap<>();
            updateColWithValue.put(AppticsConstants.REFRESHTOKEN, refreshToken);
            updateColWithValue.put(AppticsConstants.ACCESSTOKEN, accessToken);
            updateColWithValue.put(AppticsConstants.ADDEDTIME, CalendarUtil.currentTimeMillis());

            DBHandler.updateInRedis(AppticsConstants.REFRESHTOKEN, updateCriteria, updateColWithValue, zsoId);

        } else {
            Row authRow = new Row(AppticsConstants.REFRESHTOKEN);
            authRow.set(AppticsConstants.REFRESHTOKEN, refreshToken);
            authRow.set(AppticsConstants.ACCESSTOKEN, accessToken);
            authRow.set(AppticsConstants.ZUID, projectId);
            authRow.set(AppticsConstants.SERVICENAME, AppticsConstants.JIRA);
            authRow.set(AppticsConstants.ADDEDTIME, CalendarUtil.currentTimeMillis());

            DBHandler.insertRedisCacheRow(
                    authRow,
                    AppticsConstants.REFRESHTOKEN,
                    AppticsConstants.REFRESHTOKENID,
                    zsoId
            );
        }
    }
}

