195		// getting accesstoken - if it is expired refreshed again
196		public String getAccessToken(long zuID, String loginName, long apid) {
197			LOGGER.log(Level.INFO, "inside the getaccesstoken method----");
198			JSONArray tokens = getOAuthTokens(zuID);
199			String accessToken = null;
200	
201			for (int i = 0; i < tokens.length(); i++) {
202				JSONObject obj = tokens.getJSONObject(i);
203				// Just get the first Asana token for this user
204				if (obj.has("accesstoken")) {
205					accessToken = obj.getString("accesstoken");
206	
207					try {
208						String[] parts = accessToken.split("\\.");
209						if (parts.length == 3) {
210							String payload = new String(java.util.Base64.getDecoder().decode(parts[1]));
211							JSONObject claims = new JSONObject(payload);
212							long exp = claims.getLong("exp");
213							long now = System.currentTimeMillis() / 1000;
214	
215							if (now >= exp) {
216								LOGGER.log(Level.WARNING, "Access token expired! Refreshing...");
217								String refreshToken = obj.getString("refreshtoken");
218								accessToken = refreshAccessToken(zuID, refreshToken, loginName);
219							}
220						}
221					} catch (Exception e) {
222						LOGGER.log(Level.SEVERE, "Error checking token expiry", e);
223					}
224					break;
225				}
226			}
227			return accessToken;
228		}
