230		// method for refresh the access token
231		private String refreshAccessToken(long zuID, String refreshToken, String loginName) {
232			LOGGER.log(Level.INFO, "Refreshing Asana access token");
233			try {
234				String clientID = PropertyHandler.getValue(AppticsConstants.ASANACLIENTID);
235				String clientSecret = PropertyHandler.getValue(AppticsConstants.ASANACLIENTSECRET);
236	
237				Map<String, String> params = new HashMap<>();
238				params.put("grant_type", "refresh_token");
239				params.put("client_id", clientID);
240				params.put("client_secret", clientSecret);
241				params.put("refresh_token", refreshToken);
242	
243				String res = new HttpURLConnectionInvoker(true).invokePostHttpURLConn(ASANABASEURL + "-/oauth_token", null, params); // no i18N
244	
245				JSONObject response = new JSONObject(res);
246				if (response.has("access_token")) {
247					String newAccessToken = response.getString("access_token");
248					LOGGER.log(Level.INFO, " Token refreshed successfully");
249	
250					// pass loginName
251					updateAccessToken(zuID, newAccessToken, loginName);
252					return newAccessToken;
253				}
254			} catch (Exception e) {
255				LOGGER.log(Level.SEVERE, "Exception while refreshing access token", e);
256			}
257			return null;
258		}
