260		private void updateAccessToken(long zuID, String newAccessToken, String loginName) {
261			try {
262				Criteria c = new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ZUID), zuID, QueryConstants.EQUAL);
263				c = c.and(new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.SERVICENAME), AppticsConstants.ASANA, QueryConstants.EQUAL, false));
264	
265				int updated = DBHandler.update(AppticsConstants.REFRESHTOKEN, c, AppticsConstants.ACCESSTOKEN, newAccessToken, loginName);
266				LOGGER.log(Level.INFO, " Access token updated in DB, rows affected: {0}", updated);
267	
268			} catch (Exception e) {
269				LOGGER.log(Level.SEVERE, "Exception while updating access token in DB", e);
270			}
271		}
