426		// helper method
427		private JSONObject invokeAsanaAPI(String method, String url, String accessToken, JSONObject body) {
428			try {
429				java.net.URL urlObj = new java.net.URL(url);
430				javax.net.ssl.HttpsURLConnection conn = (javax.net.ssl.HttpsURLConnection) urlObj.openConnection();
431	
432				conn.setRequestMethod(method);
433				conn.setRequestProperty("Authorization", "Bearer " + accessToken);
434				conn.setRequestProperty("Content-Type", "application/json");
435				conn.setRequestProperty("Accept", "application/json");
436				conn.setConnectTimeout(10000);
437				conn.setReadTimeout(10000);
438	
439				if (body != null) {
440					conn.setDoOutput(true);
441					byte[] bodyBytes = body.toString().getBytes("UTF-8");
442					conn.setFixedLengthStreamingMode(bodyBytes.length);
443					try (java.io.OutputStream os = conn.getOutputStream()) {
444						os.write(bodyBytes);
445						os.flush();
446					}
447				}
448	
449				int responseCode = conn.getResponseCode();
450				LOGGER.log(Level.INFO, "Response code: {0}", responseCode);
451	
452				java.io.InputStream is = (responseCode >= 200 && responseCode < 300) ? conn.getInputStream() : conn.getErrorStream();
453	
454				java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.InputStreamReader(is, "UTF-8"));
455				StringBuilder responseStr = new StringBuilder();
456				String line;
457				while ((line = reader.readLine()) != null) {
458					responseStr.append(line);
459				}
460				reader.close();
461				conn.disconnect();
462	
463				LOGGER.log(Level.INFO, "Asana API response: {0}", responseStr.toString());
464	
465				if (responseCode == 200 && responseStr.toString().isEmpty()) {
466					return new JSONObject("{\"result\":\"success\"}"); // no i18N
467				}
468				return new JSONObject(responseStr.toString());
469	
470			} catch (Exception e) {
471				LOGGER.log(Level.SEVERE, "Exception in invokeAsanaAPI", e);
472			}
473			return null;
474		}
