//$Id$
package com.zoho.apptics.integration;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Level;
import java.util.logging.Logger;

import org.json.JSONArray;
import org.json.JSONObject;

import com.adventnet.ds.query.Column;
import com.adventnet.ds.query.Criteria;
import com.adventnet.ds.query.QueryConstants;
import com.adventnet.persistence.DataAccessException;
import com.adventnet.persistence.Row;
import com.zoho.apptics.util.AppticsConstants;
import com.zoho.apptics.util.CalendarUtil;
import com.zoho.apptics.util.CommonUtil;
import com.zoho.apptics.util.DBHandler;
import com.zoho.apptics.util.HttpURLConnectionInvoker;
import com.zoho.apptics.util.MickeyUtil;
import com.zoho.apptics.util.PropertyHandler;

import jakarta.servlet.http.HttpServletRequest;

public class AsanaHandler {

    private static final Logger LOGGER = Logger.getLogger(AsanaHandler.class.getName());

    private static final String ASANABASEURL = "https://app.asana.com/"; //NO I18N
	private static final String ASANASCOPE = "projects:read tasks:read tasks:write tasks:delete"; // NO I18N
    protected HttpServletRequest request;

    /*
     * Asana OAuth is stored per Apptics project (projectId), scoped to the org (zsoId), exactly like Jira.
     * The projectId is stored in the ZUID column of the REFRESHTOKEN table - no logged-in user zuid is used,
     * so the crash flow can resolve the token from data already on the crash entity.
     */
    record AsanaAuth(
            String zsoId,
            long projectId,
            String accessToken,
            String refreshToken
    ) { }

    public JSONObject getConfiguration(long apID) {
        try {
            return IntegrationHandler.getConfiguration(apID, AppticsConstants.ASANA);
       }
        catch(DataAccessException e) {
			LOGGER.log(Level.SEVERE, "Exception while getting asana configuration", e);
        }
        return null;
    }

    public JSONObject updateConfiguration(long apID, JSONObject configuration){
		LOGGER.log(Level.INFO, "INSIDE THE UPDATE CONFIGURATION METHOD------");
        try {
            new IntegrationHandler().checkAndAddConfiguration(AppticsConstants.ASANA, apID, configuration);
			LOGGER.log(Level.INFO, "AFTER CHECK AND ADD CONFIGURATION----");
          return IntegrationHandler.getConfigurationByService(apID, AppticsConstants.ASANA);
        }
        catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception while update asana configuration", e);

        }
        return null;
    }

    // authentication - asana
	public boolean authenticate(String code, String zsoId, String redirectUri, long projectId) {
		String url = ASANABASEURL + "-/oauth_token"; // no i18N

		String clientID = PropertyHandler.getValue(AppticsConstants.ASANACLIENTID);
		String clientSecret = PropertyHandler.getValue(AppticsConstants.ASANACLIENTSECRET);

		if (CommonUtil.isEmpty(clientID, clientSecret)) {
			LOGGER.log(Level.INFO, "Asana Client ID or Secret is empty");
			return false;
		}

		try {
			Map<String, String> params = new HashMap<String, String>();

			params.put("grant_type", "authorization_code");
			params.put("code", code);
			params.put("client_id", clientID);
			params.put("client_secret", clientSecret);
			params.put("redirect_uri", redirectUri);
			params.put("scope", ASANASCOPE);

			LOGGER.log(Level.INFO, "Params Map{0} ", params);

			String res = new HttpURLConnectionInvoker(true).invokePostHttpURLConn(url, null, params);

			JSONObject response = new JSONObject(res);

			LOGGER.log(Level.INFO, "response JSON{0} ", response);

			if (!response.has("access_token")) {
				LOGGER.log(Level.WARNING, "No access_token in response: {0}", res);
				return false;
			}
			String accessToken = response.getString("access_token");
			String refreshToken = response.optString("refresh_token", null);
			addOrUpdateAsanaAuth(projectId, zsoId, accessToken, refreshToken);

			LOGGER.log(Level.INFO, "Inserted/updated ASANA OAuth for project {0}", projectId);
			return true;
		} catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception while authenticating Asana", e);
		}
		return false;
	}

	private AsanaAuth getAsanaAuth(String zsoId, long projectId) {
		try {
			Criteria c = new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.SERVICENAME), AppticsConstants.ASANA, QueryConstants.EQUAL, false);
			c = c.and(new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ZUID), projectId, QueryConstants.EQUAL));

			List<Map<String, Object>> result = DBHandler.getColumnsValues(AppticsConstants.REFRESHTOKEN, c, zsoId);
			if (result != null && !result.isEmpty()) {
				Map<String, Object> row = result.get(0);
				return new AsanaAuth(
						zsoId,
						projectId,
						(String) row.get(AppticsConstants.ACCESSTOKEN),
						(String) row.get(AppticsConstants.REFRESHTOKEN)
				);
			}
		} catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception while fetching Asana auth for project " + projectId, e);
		}
		return null;
	}

	private void addOrUpdateAsanaAuth(long projectId, String zsoId, String accessToken, String refreshToken) throws Exception {
		Map<String, Object> ukcolumns = new HashMap<String, Object>();
		ukcolumns.put(AppticsConstants.ZUID, projectId);
		ukcolumns.put(AppticsConstants.SERVICENAME, AppticsConstants.ASANA);

		if (MickeyUtil.isRowExist(AppticsConstants.REFRESHTOKEN, AppticsConstants.REFRESHTOKENID, ukcolumns, zsoId)) {
			LOGGER.log(Level.INFO, "Asana auth already exists for project {0}. Updating tokens.", projectId);

			Criteria c = new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.SERVICENAME), AppticsConstants.ASANA, QueryConstants.EQUAL, false);
			c = c.and(new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ZUID), projectId, QueryConstants.EQUAL));

			DBHandler.update(AppticsConstants.REFRESHTOKEN, c, AppticsConstants.ACCESSTOKEN, accessToken, zsoId);
			if (refreshToken != null) {
				DBHandler.update(AppticsConstants.REFRESHTOKEN, c, AppticsConstants.REFRESHTOKEN, refreshToken, zsoId);
			}
		} else {
			Row row = new Row(AppticsConstants.REFRESHTOKEN);
			row.set(AppticsConstants.REFRESHTOKEN, refreshToken);
			row.set(AppticsConstants.ACCESSTOKEN, accessToken);
			row.set(AppticsConstants.ZUID, projectId);
			row.set(AppticsConstants.SERVICENAME, AppticsConstants.ASANA);
			row.set(AppticsConstants.ADDEDTIME, CalendarUtil.currentTimeMillis());

			List<Row> rows = new ArrayList<>();
			rows.add(row);
			DBHandler.insertRows(rows, zsoId);
		}
	}

	public JSONArray getOAuthTokens(String zsoId, long projectId) {
		JSONArray tokens = new JSONArray();
		try {
			Criteria c = new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ZUID), projectId, QueryConstants.EQUAL);
			c = c.and(new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.SERVICENAME), AppticsConstants.ASANA, QueryConstants.EQUAL, false));

			List<Map<String, Object>> result = DBHandler.getColumnsValues(AppticsConstants.REFRESHTOKEN, c, zsoId);

			if (result == null || result.isEmpty()) {
				LOGGER.log(Level.INFO, "No Asana token found for project = {0}", new Object[] { projectId });
				return tokens;
			}

			for (Map<String, Object> row : result) {
				JSONObject token = new JSONObject();
				token.put("asanaid", row.get(AppticsConstants.REFRESHTOKENID));
				token.put("addedtime", row.get(AppticsConstants.ADDEDTIME));
				token.put("refreshtoken", row.get(AppticsConstants.REFRESHTOKEN));
				token.put("accesstoken", row.get(AppticsConstants.ACCESSTOKEN));
				tokens.put(token);
			}
		} catch (DataAccessException e) {
			LOGGER.log(Level.SEVERE, "Exception while fetching Asana OAuth token", e);
		}
		return tokens;
	}

	// getting accesstoken - if it is expired refreshed again
	public String getAccessToken(String zsoId, long projectId) {
		AsanaAuth auth = getAsanaAuth(zsoId, projectId);
		if (auth == null) {
			LOGGER.log(Level.SEVERE, "Asana auth not found for project {0}", projectId);
			return null;
		}

		String accessToken = auth.accessToken();
		try {
			String[] parts = accessToken.split("\\.");
			if (parts.length == 3) {
				String payload = new String(java.util.Base64.getDecoder().decode(parts[1]));
				JSONObject claims = new JSONObject(payload);
				long exp = claims.getLong("exp");
				long now = System.currentTimeMillis() / 1000;

				if (now >= exp) {
					LOGGER.log(Level.WARNING, "Asana access token expired. Refreshing...");
					accessToken = refreshAccessToken(zsoId, projectId, auth.refreshToken());
				}
			}
		} catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Error checking Asana token expiry", e);
		}
		return accessToken;
	}

	// method for refresh the access token
	private String refreshAccessToken(String zsoId, long projectId, String refreshToken) {
		LOGGER.log(Level.INFO, "Refreshing Asana access token");
		try {
			String clientID = PropertyHandler.getValue(AppticsConstants.ASANACLIENTID);
			String clientSecret = PropertyHandler.getValue(AppticsConstants.ASANACLIENTSECRET);

			Map<String, String> params = new HashMap<>();
			params.put("grant_type", "refresh_token");
			params.put("client_id", clientID);
			params.put("client_secret", clientSecret);
			params.put("refresh_token", refreshToken);

			String res = new HttpURLConnectionInvoker(true).invokePostHttpURLConn(ASANABASEURL + "-/oauth_token", null, params); // no i18N

			JSONObject response = new JSONObject(res);
			if (response.has("access_token")) {
				String newAccessToken = response.getString("access_token");
				LOGGER.log(Level.INFO, "Asana token refreshed successfully");

				updateAccessToken(zsoId, projectId, newAccessToken);
				return newAccessToken;
			}
		} catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception while refreshing Asana access token", e);
		}
		return null;
	}

	private void updateAccessToken(String zsoId, long projectId, String newAccessToken) {
		try {
			Criteria c = new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.ZUID), projectId, QueryConstants.EQUAL);
			c = c.and(new Criteria(Column.getColumn(AppticsConstants.REFRESHTOKEN, AppticsConstants.SERVICENAME), AppticsConstants.ASANA, QueryConstants.EQUAL, false));

			int updated = DBHandler.update(AppticsConstants.REFRESHTOKEN, c, AppticsConstants.ACCESSTOKEN, newAccessToken, zsoId);
			LOGGER.log(Level.INFO, "Asana access token updated in DB, rows affected: {0}", updated);

		} catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception while updating Asana access token in DB", e);
		}
	}

	// getting all the workspace id and names
	public List<JSONObject> getAllWorkspaces(String zsoId, long projectId) {
        LOGGER.log(Level.INFO,"Getting all the workspace Id");
        ArrayList<JSONObject> workspaceList = new ArrayList<>();
        String url = ASANABASEURL+"api/1.0/workspaces";  //no i18N

		String accessToken = getAccessToken(zsoId, projectId);

        if (accessToken == null) {
            LOGGER.log(Level.SEVERE, "Access token not found");
            return workspaceList;
        }
        Map<String, String> headers = new HashMap<String, String>();
        headers.put("Authorization", "Bearer "+accessToken);
        headers.put("Content-Type", "application/json");

        try {
			String res = new HttpURLConnectionInvoker(true).invokeGetHttpURLConn(url, headers, null);

            JSONObject response = new JSONObject(res);
            JSONArray result = response.getJSONArray("data"); //no i18N
            for(int i =0;i< result.length();i++) {
                JSONObject workspaceIDObj = result.getJSONObject(i);
                workspaceList.add(workspaceIDObj);
            }
        }catch (Exception e) {
            LOGGER.info("Exception while fetching Asana workspaces "+ e);
        }
        return workspaceList;
    }

	// get particular workspace ID by workspace name
	public String getWorkSpaceIDByName(String zsoId, long projectId, String workspaceName) {
		List<JSONObject> workspaces = getAllWorkspaces(zsoId, projectId);
        for (JSONObject workspace : workspaces) {
            String name = workspace.getString("name");

            if (name.equalsIgnoreCase(workspaceName)) {
                return workspace.getString("gid");
            }
        }
        return null;
    }

    //get all the projects present inside the particular workspace
	public List<JSONObject> getAllProjects(String zsoId, long projectId, String workspaceGid) {
		LOGGER.log(Level.INFO, "Getting projects for workspace:  {0}", workspaceGid);

        List<JSONObject> projects = new ArrayList<>();
        String url = ASANABASEURL + "api/1.0/projects?workspace=" + workspaceGid;    //no i18N

		String accessToken = getAccessToken(zsoId, projectId);
        Map<String, String> headers = new HashMap<String, String>();
        if (accessToken == null) {
            LOGGER.log(Level.SEVERE, "Access token not found");
            return null;
        }
		headers.put("Authorization", "Bearer " + accessToken);
		headers.put("Content-Type", "application/json");

        try {
			String res = new HttpURLConnectionInvoker(true).invokeGetHttpURLConn(url, headers, null);

            JSONObject response = new JSONObject(res);
            JSONArray result = response.getJSONArray("data");   //no i18N
            for(int i =0;i< result.length();i++) {
                JSONObject workspaceIDObj = result.getJSONObject(i);
                projects.add(workspaceIDObj);
            }
        }catch (Exception e) {
            LOGGER.info("Exception while fetching Asana projects "+ e);
        }
        return projects;
    }

	public Long getProjectGidByName(String zsoId, long projectId, String workspaceGid, String projectName) {

		LOGGER.log(Level.INFO, "Getting project GID for project name: {0}", projectName);
		List<JSONObject> projects = getAllProjects(zsoId, projectId, workspaceGid);

        for (JSONObject project : projects) {
            if (!project.has("name") || !project.has("gid")) {
                continue;
            }

            String name = project.getString("name");

            if (name.equalsIgnoreCase(projectName)) {
                try {
                    return Long.parseLong(project.getString("gid"));
                } catch (NumberFormatException e) {
					LOGGER.log(Level.SEVERE, "Could not parse GID to Long: {0}", project.getString("gid"));
                    return null;
                }
            }
        }
        return null;
    }

	public JSONObject addAsanaTask(String zsoId, long projectId, String workspaceGid, String projectGid, String taskName, String taskdescription, String assigneeGid) {
		LOGGER.log(Level.INFO, "Adding task in Asana");

		String accessToken = getAccessToken(zsoId, projectId);
		if (accessToken == null) {
			LOGGER.log(Level.SEVERE, "Access token not found");
			return null;
		}

		String url = ASANABASEURL + "api/1.0/tasks"; // no i18N

		Map<String, String> headers = new HashMap<>();
		headers.put("Authorization", "Bearer " + accessToken);
        headers.put("Content-Type", "application/json");

		try {
			// Asana requires JSON body with "data" wrapper
			JSONObject data = new JSONObject();
			data.put("name", taskName);
			data.put("workspace", workspaceGid);

			if (!CommonUtil.isEmpty(projectGid)) {
				JSONArray projects = new JSONArray();
				projects.put(projectGid);
				data.put("projects", projects);
			}
			if (!CommonUtil.isEmpty(taskdescription)) {
				data.put("notes", taskdescription);
			}
			if (!CommonUtil.isEmpty(assigneeGid)) {
				data.put("assignee", assigneeGid);
            }

			JSONObject body = new JSONObject();
			body.put("data", data);

			LOGGER.log(Level.INFO, "Asana create task request body: {0}", body.toString());

			// Send as JSON body not form params
			JSONObject result = new HttpURLConnectionInvoker(true).invokeHttpURLConn(1, url, headers, body, null, false); // 1 = POST

			LOGGER.log(Level.INFO, "Asana create task response: {0}", result);
			return result;

		} catch (Exception e) {
			LOGGER.info("Exception while adding task in Asana: " + e);
        }
		return null;
    }

	/*
	 * Internal call used by the crash flow - mirrors JiraHandler.sendToJira.
	 * No app/role validation and no logged-in user; the OAuth token is resolved
	 * from (zsoId, projectId) and the workspace/project from the integration config (apId).
	 */
	public boolean sendToAsana(String zsoId, long projectId, long apId, String taskTitle, String taskDescription, String crashLink) {
		try {
			String accessToken = getAccessToken(zsoId, projectId);
			if (accessToken == null) {
				LOGGER.log(Level.INFO, "Asana access token not found for project {0}", projectId);
				return false;
			}

			JSONObject asanaConfig = getConfiguration(apId);
			if (asanaConfig == null) {
				LOGGER.log(Level.INFO, "Asana config not found for apId {0}", apId);
				return false;
			}

			JSONObject configuration = asanaConfig.optJSONObject("Configuration");
			if (configuration == null) {
				LOGGER.log(Level.INFO, "Asana configuration object is null for apId {0}", apId);
				return false;
			}

			String workspaceGid = configuration.optString("workspaceGid", null);
			String projectGid = configuration.optString("projectGid", null);

			LOGGER.log(Level.INFO, "ASANA workspaceGid {0}, projectGid {1}", new Object[] { workspaceGid, projectGid });

			if (CommonUtil.isEmpty(workspaceGid, projectGid)) {
				LOGGER.log(Level.INFO, "Asana workspaceGid/projectGid missing for apId {0}", apId);
				return false;
			}

			String taskDesc = crashLink + "\n\n" + taskDescription; // no i18N

			JSONObject result = addAsanaTask(zsoId, projectId, workspaceGid, projectGid, taskTitle, taskDesc, null);
			LOGGER.log(Level.INFO, "Asana task creation result: {0}", result);
			return result != null && result.has("data");

		} catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception while sending crash to Asana", e);
		}
		return false;
	}

	public JSONObject updateAsanaTask(String zsoId, long projectId, String taskGid, String taskname, String taskdescription, String assigneeGid, String approvalStatus) {

        LOGGER.log(Level.INFO, "Updating task in Asana");

        JSONObject response = null;

        try {
			String accessToken = getAccessToken(zsoId, projectId);

            Map<String, String> headers = new HashMap<>();
            headers.put("Authorization", "Bearer " + accessToken);
            headers.put("Content-Type", "application/json");

			String url = ASANABASEURL + "api/1.0/tasks/" + taskGid; // no i18n

            JSONObject data = new JSONObject();

            if (!CommonUtil.isEmpty(taskname)) {
                data.put("name", taskname);
            }

            if (!CommonUtil.isEmpty(taskdescription)) {
                data.put("notes", taskdescription); // no i18N Asana uses "notes"
            }

            if (!CommonUtil.isEmpty(assigneeGid)) {
                data.put("assignee", assigneeGid);
            }

            if (!CommonUtil.isEmpty(approvalStatus)) {
                data.put("approval_status", approvalStatus);
            }

            JSONObject body = new JSONObject();
            body.put("data", data);
			response = new HttpURLConnectionInvoker(true).invokeHttpURLConn(3, url, headers, body, null, false);

        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Exception while updating task in Asana", e);
        }

        return response;
    }

	public JSONObject getTask(String zsoId, long projectId, String taskGid) {
		LOGGER.log(Level.INFO, "Getting task from Asana: {0}", taskGid);

		try {
			String accessToken = getAccessToken(zsoId, projectId);
			if (accessToken == null) {
				LOGGER.log(Level.SEVERE, "Access token not found");
				return null;
			}

			String url = ASANABASEURL + "api/1.0/tasks/" + taskGid; // no i18N

			Map<String, String> headers = new HashMap<>();
			headers.put("Authorization", "Bearer " + accessToken);
			headers.put("Content-Type", "application/json");

			String res = new HttpURLConnectionInvoker(true).invokeGetHttpURLConn(url, headers, null);

			JSONObject response = new JSONObject(res);
			if (response.has("data")) {
				return response.getJSONObject("data");
			}

		} catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception while getting task from Asana", e);
		}
		return null;
	}

    // to delete a particular task
	public JSONObject deleteAsanaTask(String zsoId, long projectId, String taskGid) {

        LOGGER.log(Level.INFO, "Deleting task in Asana");
        try {
			String accessToken = getAccessToken(zsoId, projectId);
            if (accessToken == null) {
                LOGGER.log(Level.SEVERE, "Access token not found");
                return null;
            }
            Map<String, String> headers = new HashMap<>();
            headers.put("Authorization", "Bearer " + accessToken);
            headers.put("Content-Type", "application/json");

            String url = ASANABASEURL + "api/1.0/tasks/" + taskGid; // no i18N
			return new HttpURLConnectionInvoker(true).invokeDeleteHttpURLConn(url, headers, null, null, false);

        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Exception while deleting task in Asana", e);
        }
        return null;
    }
}

