		crashEntity.setAppReleaseVerTag(AppReleaseVersionHandler.getAppReleaseVersionTagByID(crashEntity.getAppReleaseVersionID()));
		crashEntity.setMode( AppHandler.getInstance().getTypeByAAID(crashEntity.getAaID()));

		ScreenData screenData = ScreenUtil.getInstance().getScreenData(crashEntity.getProjectID(), crashEntity.getScreenName(), crashEntity.getPlatformID());
		crashEntity.setScreenTag(screenData.getScreenTag());
		crashEntity.setScreenID(screenData.getScreenID());

		List<Object> osVersionDetails = OSVersionHandler.getInstance().getOSVersionAndIDByTag(crashEntity.getOsVersionTag());
		crashEntity.setOsVersion((String) osVersionDetails.get(1));
		crashEntity.setOsVersionID((Long) osVersionDetails.get(0));

		Integer modelTag =crashEntity.getModelTag();
		crashEntity.setDeviceModel(DeviceHandler.getModelByTag(modelTag));
		crashEntity.setModelID(DeviceHandler.getModelIDByTag(modelTag));

		Integer timezoneTag =crashEntity.getTimezoneTag();
		crashEntity.setTimezone(TimezoneHandler.getZoneByTag(timezoneTag));
		crashEntity.setTimeZoneID(TimezoneHandler.getTimeZoneIDByTag(timezoneTag));

		crashEntity.setBrandID(PlatformHandler.getInstance().getPlatformBrandIDByPlatformId(crashEntity.getPlatformID()));
		crashEntity.setSdID(SupportedDevicehandler.getInstance().getSDIDByTag(crashEntity.getSdIDTag()));


		//crashEntity.setCountryTag(CountryHandler.getInstance().getCountryTagByCountryID(crashEntity.getCountryID()));
		crashEntity.setOrientation(OrientationHandler.getOrientationByTag(crashEntity.getOrientationTag()));

		setUniqueID(crashEntity);

		ExceptionsHandler.addReports(crashEntity);
	}

	private static Long setUniqueID(CrashEntity crashEntity) throws Exception{
        Map<Long, Boolean> isUniqueMap = new LinkedHashMap<Long, Boolean>(); 
        Long uniqueId;

		if (crashEntity.getExceptionGroup().equalsIgnoreCase(AppticsConstants.FATAL)) {
			 isUniqueMap = SDKCache.getInstance().getFatalExpUniqueID(crashEntity);
			 uniqueId=  isUniqueMap.keySet().iterator().next();
		} else if (crashEntity.getExceptionGroup().equalsIgnoreCase(AppticsConstants.NONFATAL)) {
			 //isUniqueMap = SDKCache.getInstance().getNonFatalExpUniqueID(crashEntity);
			 //uniqueId=  isUniqueMap.keySet().iterator().next();
			 uniqueId = 0l;
		} else if (crashEntity.getExceptionGroup().equalsIgnoreCase(AppticsConstants.ANR)) {
			 isUniqueMap = SDKCache.getInstance().getAnrExpUniqueID(crashEntity);
			 uniqueId=  isUniqueMap.keySet().iterator().next();
		}
		else { //Getting webError
			isUniqueMap = SDKCache.getInstance().getErrorExpUniqueID(crashEntity);
			 uniqueId=  isUniqueMap.keySet().iterator().next();
		}


		crashEntity.setUniqueID(uniqueId); 
		crashEntity.setIsNewUniqueID(isUniqueMap.get(uniqueId));

		return uniqueId;

	}


