	public static Map<String, Long> getUniqueMessages(Long fromDate, Long projectId, String tablename) {
		LOGGER.log(Level.INFO, "getUniqueMessages {0}, fromDate {1}, tablename {2}", new Object[] { projectId, fromDate, tablename });

		Map<String, Long> uniqueMessages = new LinkedHashMap<String, Long>();
		String query = "select distinct uniquemessageID, Issuename from " + tablename + " where inserttime>=" + fromDate; // NO I18N

		List<List<String>> values;
		try {
			values = BDassClient.executeQuery(projectId, null, query);

			Iterator<List<String>> iterator = values.iterator();
			while (iterator.hasNext()) {
				List<String> row = iterator.next();

				Long uniqueid = 0l;
				if(!CommonUtil.isEmpty(row.get(0)))
				{
					uniqueid = Long.parseLong(row.get(0));
				}
				uniqueMessages.put(row.get(1), uniqueid);
			}
		} catch (Exception e) {
			LOGGER.log(Level.INFO, "Exception while getUniqueMessages", e);
		}

		LOGGER.log(Level.INFO, "uniqueMessages size {0}", uniqueMessages.size());
		return uniqueMessages;

	}

