	public static void processFlutterReport(CrashEntity crashEntity) {

		try {

			String message = crashEntity.getMessage();

			String crashdetails[] = null;
			String issueName = AppticsConstants.UNSYMBOLICATED;

			Pattern pattern = Pattern.compile("arch:\\s*([\\w\\d]+)");
			Matcher matcher = pattern.matcher(crashEntity.getMessage());
			String architecture = null;
			if (matcher.find()) {
				architecture = matcher.group(1).trim();
			}

			if (CommonUtil.isEmpty(architecture)) {
				crashEntity.setIssueName(issueName);
				addApplicationReport(crashEntity);
			}

			LOGGER.log(Level.INFO, "Calling fetch flutter symbol file");

			String entityName = "app.android-" + architecture + ".symbols";
			if (crashEntity.getPlatform().equalsIgnoreCase(AppticsConstants.IOS)) {
				entityName = "app.ios-" + architecture + ".symbols";
			}

			File symbolFile = fetchFile(AppticsConstants.BUILDFILES, crashEntity);

			File unzipFile = !CommonUtil.isEmpty(symbolFile) ? unzipFile(symbolFile, entityName) : null;

			if (!CommonUtil.isEmpty(unzipFile)) {

				String symbolicatemsg = processHybridSymbolication(crashEntity.getMessage(), unzipFile, crashEntity.getCrashType() == AppticsConstants.EXCEPTIONTYPE_FLUTTER);

				if (!CommonUtil.isEmpty(symbolicatemsg)) {
					if (crashEntity.getCrashType().equals(AppticsConstants.EXCEPTIONTYPE_FLUTTER)) {

						if (symbolicatemsg.contains("#0")) {
							symbolicatemsg = symbolicatemsg.substring(symbolicatemsg.indexOf("#0"));
						}
						String crash = "";
						crashdetails = symbolicatemsg.trim().split("\n");
						Integer line = 0;
						for (String crashline : crashdetails) {
							crashline = crashline.replace("#" + line++, "").trim();
							crashline = crashline.replace(crashline.substring(crashline.indexOf("(") + 1, crashline.lastIndexOf("/") + 1), "");

							crash += crashline + "\n";
						}

						message = crash;
						issueName = crash.substring(0, crash.indexOf("\n"));
					}
				}
			}

			crashEntity.setMessage(CommonUtil.maskPII(message));
			crashEntity.setIssueName(CommonUtil.maskPII(issueName));

			CommonUtil.deleteTmpFileInAppServer(symbolFile);
		} catch (Exception e) {
			LOGGER.log(Level.INFO, "Exception While processing Flutter Crash",e);
		}

	}


	public static String processHybridSymbolication(String message, File file, Boolean isFlutter) {

		LOGGER.log(Level.INFO, "Calling symboication process");

		StringBuilder result = new StringBuilder();
		String command = null;

		BufferedReader reader = null;
		FileWriter wr = null;
		File path = null;

		try {
			path = new File("stactrace.txt");

			wr = new FileWriter(path);
			wr.write(message);
			wr.flush();
			wr.close();

			LOGGER.log(Level.INFO, "symbol file - > {0}", file);
			LOGGER.log(Level.INFO, "message is - > {0}", message);

			LOGGER.log(Level.INFO, "symbole file path -> {0}", file.getAbsolutePath());
			LOGGER.log(Level.INFO, "stacktrace path -> {0}", path.getAbsolutePath());


			if (isFlutter) {
				LOGGER.log(Level.INFO, "Flutter Symbolication");
				command = "flutter symbolize -i " + path + " -d " + file;

				try {

						LOGGER.log(Level.INFO, "Disable telemetry");
						ProcessBuilder processBuilder = new ProcessBuilder("/bin/bash", "-c", "flutter --disable-telemetry");

						processBuilder.redirectErrorStream(true);
						Process process = processBuilder.start();

						int exitCode = process.waitFor();
						LOGGER.log(Level.INFO, "Exit Code - > {0}", exitCode);

					}

				 catch (Exception e) {

					LOGGER.log(Level.INFO, "Exception while disabling telemetry");
				}
			} else {
				LOGGER.log(Level.INFO, "React Symbolication");
				command = "metro-symbolicate " + file + " < " + path;
			}

			LOGGER.log(Level.INFO, "Command is {0}", command);

			ProcessBuilder processBuilder = new ProcessBuilder("/bin/bash", "-c", command);

			processBuilder.redirectErrorStream(true);

			Process process = processBuilder.start();
			reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
			String line = null;

			while ((line = reader.readLine()) != null) {

				result.append(line).append("\n");
			}

			LOGGER.log(Level.INFO, "result is -> {0}", result);

			int exitCode = process.waitFor();
			LOGGER.log(Level.INFO, "Exit Code - > {0}", exitCode);

		} catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception while symbolicate crash - >{0} ", e);
		}

		finally {
			try {	

				reader.close();
				CommonUtil.deleteTmpFileInAppServer(file);
				CommonUtil.deleteTmpFileInAppServer(path);		

			} catch (IOException e) {
				LOGGER.log(Level.SEVERE, "Exception while closing BufferedReader and writer - > {0}", e);
			}
		}
		return result.toString();
	}

	private static File unzipFile(File symbolFile, String entityName) {
		File outputFile = null;
		ZipFile zipFile = null;

		FileOutputStream outputStream = null;
		InputStream inputStream = null;

		try {

			zipFile = new ZipFile(symbolFile.getAbsolutePath());
			ZipEntry entry = zipFile.getEntry(entityName);
			LOGGER.log(Level.INFO, "Entry{0}", entry);

			LOGGER.log(Level.INFO, "Build File path -> {0}", symbolFile.getAbsolutePath());

			if (entry != null) {

				inputStream = zipFile.getInputStream(entry);

				outputFile = new File("build.txt");
				LOGGER.log(Level.INFO, "outputFile : {0}", outputFile);
				outputStream = new FileOutputStream(outputFile);

			}

			LOGGER.log(Level.INFO, "outputStream : {0}", outputStream);

			byte[] buffer = new byte[1024];
			int bytesRead;
			while ((bytesRead = inputStream.read(buffer)) != -1) {
				outputStream.write(buffer, 0, bytesRead);
			}

		} catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception while Unzip the file", e);
		} finally {

			try {
				outputStream.close();
				inputStream.close();
				zipFile.close();
			} catch (Exception e) {
				LOGGER.log(Level.SEVERE, "Exception while closing Streams ", e);
			}
		}
		LOGGER.log(Level.INFO, "outputFile : {0}", outputFile);

		return outputFile;
	}


	public static void addBuildFile(Long appID, Long appversionid, Long apid, HttpServletRequest request, Long appreleaseversionid, String crashtype) throws Exception {

		try {

			String blockID = "";
			Long addedTime = System.currentTimeMillis();

			Long addedBy = 0L;

			ArrayList<UploadedFileItem> fileItems = (ArrayList<UploadedFileItem>) request.getAttribute(SecurityUtil.MULTIPART_FORM_REQUEST);
			String fileName = "";
			if (fileItems == null) {
				LOGGER.log(Level.INFO, "File not attached");
				return;
			} else {
				for (UploadedFileItem fileItem : fileItems) {

					fileName = appversionid + "_" + addedTime + ".zip";

					LOGGER.log(Level.INFO, "File name of build -> {0}", fileName);
					blockID = DFSFileHandler.dfsFileUpload(fileItem, fileName, appID);
				}
			}

            Long id = 0L;

			SelectQuery sq = new SelectQueryImpl(Table.getTable(AppticsConstants.BUILDFILES));
			sq.addSelectColumn(Column.getColumn(AppticsConstants.BUILDFILES, AppticsConstants.APPVERSIONID));
			sq.addSelectColumn(Column.getColumn(AppticsConstants.BUILDFILES, AppticsConstants.BUILDFILEID));
			sq.addSelectColumn(Column.getColumn(AppticsConstants.BUILDFILES, AppticsConstants.APPRELEASEVERSIONID));
			sq.addSelectColumn(Column.getColumn(AppticsConstants.BUILDFILES, AppticsConstants.CRASHTYPE));

			Criteria criteria = new Criteria(Column.getColumn(AppticsConstants.BUILDFILES, AppticsConstants.APID), apid, QueryConstants.EQUAL).and(Column.getColumn(AppticsConstants.BUILDFILES, AppticsConstants.APPVERSIONID), appversionid, QueryConstants.EQUAL).and(Column.getColumn(AppticsConstants.BUILDFILES, AppticsConstants.APPRELEASEVERSIONID), appreleaseversionid, QueryConstants.EQUAL);
			sq.setCriteria(criteria);

			Persistence per = DBHandler.getPersistence();
			DataObject dobj = per.get(sq);

			if (dobj.containsTable(AppticsConstants.BUILDFILES)) {
				LOGGER.log(Level.INFO, "File exist");

				Row row = dobj.getFirstRow(AppticsConstants.BUILDFILES);

				row.set(AppticsConstants.DFSFILEPATH, fileName);
				row.set(AppticsConstants.BLOCKID, blockID);
				row.set(AppticsConstants.ADDEDBY, addedBy);
				row.set(AppticsConstants.ADDEDTIME, addedTime);

                id = (Long) row.get(AppticsConstants.BUILDFILEID);

				dobj.updateRow(row);
				per.update(dobj);

			} else {

				Integer type = getcrashtype(crashtype);

				Row r = new Row(AppticsConstants.BUILDFILES);
				r.set(AppticsConstants.APID, apid);
				r.set(AppticsConstants.APPVERSIONID, appversionid);
				r.set(AppticsConstants.BLOCKID, blockID);
				r.set(AppticsConstants.DFSFILEPATH, fileName);
				r.set(AppticsConstants.ADDEDTIME, addedTime);
				r.set(AppticsConstants.APPRELEASEVERSIONID, appreleaseversionid);
				r.set(AppticsConstants.ADDEDBY, addedBy);
				r.set(AppticsConstants.CRASHTYPE, type);

				id = DBHandler.insertRow(r, AppticsConstants.BUILDFILES, AppticsConstants.BUILDFILEID);
			}

            NativeExceptionHandler.upsertBuildFileDualWrite(id, appID, appversionid, appreleaseversionid, apid, blockID, fileName, addedTime, "", "", "insert", "", AppticsConstants.CRASHTYPE_FLUTTER);

		} catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Exception while adding the build file", e);
			throw new Exception("Exception while adding file", e);
		}
	}

	private static File fetchFile(String tableName, CrashEntity crashentity) {

		LOGGER.log(Level.INFO, "Fetch file from the table {0}", tableName);

		SelectQuery sq = new SelectQueryImpl(Table.getTable(tableName));
		sq.addSelectColumn(Column.getColumn(tableName, "*"));

		Criteria c;

		if (tableName.equals(AppticsConstants.DSYMTABLE)) {
			c = new Criteria(Column.getColumn(tableName, AppticsConstants.APPVERSIONID), crashentity.getAppVersionID(), QueryConstants.EQUAL);
			c = c.and(new Criteria(Column.getColumn(tableName, AppticsConstants.APPRELEASEVERSION), crashentity.getAppReleaseVersion(), QueryConstants.EQUAL));
		}
		else if(tableName.equals(AppticsConstants.BUILDMAPPINGFILES)) {

			c = new Criteria(Column.getColumn(tableName, AppticsConstants.APPVERSION),crashentity.getAppReleaseVersion(), QueryConstants.EQUAL);
			c = c.and(new Criteria(Column.getColumn(tableName, "AppVersionName"), crashentity.getAppVersion(), QueryConstants.EQUAL)
					.and(Column.getColumn(tableName,AppticsConstants.PACKAGEID), crashentity.getApID(), QueryConstants.EQUAL));

		}
		else { //for react native and flutter
			c = new Criteria(Column.getColumn(tableName, AppticsConstants.APPVERSIONID), crashentity.getAppVersionID(), QueryConstants.EQUAL);
			c = c.and(new Criteria(Column.getColumn(tableName, AppticsConstants.APPRELEASEVERSIONID), crashentity.getAppReleaseVersionID(), QueryConstants.EQUAL));
		}
		sq.setCriteria(c);

		DataObject dobj = null;

		try {
			dobj = DBHandler.getPersistence().get(sq);
			if (!dobj.containsTable(tableName)) {
				LOGGER.log(Level.INFO, "Table not found");
				return null;
			}
			Row r = dobj.getFirstRow(tableName);

			String dfspath = (String) r.get(AppticsConstants.DFSFILEPATH);
			String blockID = (String) r.get(AppticsConstants.BLOCKID);

			LOGGER.log(Level.INFO, "dfsPath -> {0}, blockID --> {1}", new Object[] { dfspath, blockID });

			File buildfile = DFSFileHandler.dfsFileReadReturnFile(dfspath, blockID, crashentity.getProjectID());		

			if (!CommonUtil.isEmpty(buildfile) && tableName.equals(AppticsConstants.DSYMTABLE)) {
				crashentity.setDsymPath(dfspath);
			}

			return buildfile;

		} catch (Exception e) {
			LOGGER.log(Level.INFO, "Exception while fetching build file");
			return null;
		}
	}


	private static String copyDSymFiletoMac(CrashEntity crashentity, File f, String fileName, DSymServer mac, String buildLocation,String processFor) {

		String host = mac.host;
		String pass = mac.password;
		String username = mac.username;
		String result= "";

		LOGGER.log(Level.INFO,"Copy the dsym file to mac machine {0}",host);


		try {
			SshExecutor.executeCommand(new SshConfig(host, username, pass, "mkdir -p " + AppticsConstants.DSYMFILELOCATION));
		} catch (Exception e) {
			LOGGER.info("Exception in permission");
			host = mac.removeNode(crashentity.getProjectID());
		}

		try {

			SshConfig config = new SshConfig(host, username, pass, f.getAbsolutePath(), AppticsConstants.DSYMFILELOCATION + fileName); // config - Connection detail and file names

			SshExecutor.copyLocalFileToRemoteHost(config);

			LOGGER.log(Level.INFO,"using ditto to unzip the dsym");

			SshExecutor.executeCommand(new SshConfig(host, username, pass, "rm -rvf " + buildLocation + "; ditto -x -k " + AppticsConstants.DSYMFILELOCATION + fileName + " " + buildLocation));

			SshExecutor.executeCommand(new SshConfig(host, username, pass, "rm -rvf " + AppticsConstants.DSYMFILELOCATION + fileName));


			if(processFor.equals(AppticsConstants.FILEUPLOAD)) {
			String command;			

			String reFile = SshExecutor.executeCommand(new SshConfig(host, username, pass, "find " + buildLocation + " -maxdepth 1  -name \"*.dSYM\""));

			command = "dwarfdump -u " + buildLocation + "/*.app.dSYM";

			if (CommonUtil.isEmpty(reFile)) {
				command = "dwarfdump -u " + buildLocation + "/**/*.app.dSYM";
			}

			else if (reFile.trim().split("\\.dSYM").length == 1) {
				LOGGER.log(Level.INFO, "Change the wrong name");
				String reName = reFile.substring(reFile.lastIndexOf("/")).trim();
				reName = reName.replace(".", "_");
				SshExecutor.executeCommand(new SshConfig(host, username, pass, "mv " + buildLocation + "/*.dSYM " + buildLocation + reName));
				command = "dwarfdump -u " + buildLocation + reName + "/*.app.dSYM";
			}		


				try {		
					   LOGGER.info("Get uuid of dsym file");

						SshConfig config1 = new SshConfig(host, username, pass, command);

					    result = SshExecutor.executeCommand(config1);
						result = result.replace(" ", "");
						result = result.substring(result.indexOf(":") + 1, result.indexOf("("));
						result = result.replaceAll("-", "").toLowerCase();

						LOGGER.log(Level.INFO, "uuid is {0}", result);

					} catch (Exception e) {
						LOGGER.log(Level.INFO, "Exception while getting uuid :", e);

					}
				try {
					LOGGER.log(Level.INFO, "Remove the folder from mac");
					SshExecutor.executeCommand(new SshConfig(host, username, pass, "rm -rvf " + buildLocation));
				} catch (Exception e) {
					LOGGER.log(Level.INFO, "Not Contain the folder");
				}
			}

		}catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Dsym File: ", e);
		}

		finally {

			CommonUtil.deleteTmpFileInAppServer(f);
		}
		return result;
	}


