	public static void processNativeSymboliction(CrashEntity crashentity) throws Exception {

		LOGGER.log(Level.INFO,"Calling ProcessNativeSymbolication Method");

		String issueName = AppticsConstants.UNSYMBOLICATED + " - " + crashentity.getCrashGroupString();
		String message = crashentity.getMessage();

		final String disabledApID =PropertyHandler.getValue(SdkConstants.DISBALEDSYMBOLICATIONAPID);
		if(disabledApID!=null && disabledApID.contains(crashentity.getApID()+"")) {
			LOGGER.log(Level.INFO, "Symbolication disabled for the apid {0}",crashentity.getApID());
			return;
		}

		File dsymfile = fetchFile(AppticsConstants.DSYMTABLE, crashentity);

		if(CommonUtil.isEmpty(dsymfile)) {
			LOGGER.log(Level.INFO,"Dsym file not there");
			String displayName = ProjectHandler.getDisplayName(crashentity.getProjectID());
			issueName = "Missing dSYMs for [" + displayName + "]";
			crashentity.setIssueName(CommonUtil.maskPII(issueName));
			crashentity.setMessage(CommonUtil.maskPII(crashentity.getMessage()));
			return;
		}

		LOGGER.log(Level.INFO,"Calling symbolication process");

		String crash = "";
		JSONObject crashdetails = new JSONObject();

		try {
			DSymServer mac = DSymServer.getInstatnce(crashentity.getProjectID());
			String host = mac.host;
			String username = mac.username;
			String pass = mac.password;

			LOGGER.log(Level.INFO,"mac server is {0}",host);

			//Long symid = updateDsymFile(crashentity, mac);

			String symid = crashentity.getDeviceID() + "_" + crashentity.getHappenedAt();

			String cfile = "C_" + symid + ".crash"; 
			String symfile = "s_" + symid;

			String dsymName = crashentity.getAppVersionID() + "-" + crashentity.getAppReleaseVersion()+"_dSYM";

			String buildlocation = BUILDLOCATION + dsymName;
			String crashlocation = CRASHLOCATION + cfile;
			String desymlocation = DESYMLOCATION + symfile;
			String scriptlocation = SCRIPTLOCATION + "symbolicateHelper.sh";

			LOGGER.log(Level.INFO, "scriptlocation - {0}, crashlocation - {1}, desymlocation - {2} , buildlocation - {3}", new Object[] { scriptlocation, crashlocation, desymlocation, buildlocation });

			SshConfig config = new SshConfig(host, username, pass, cfile, CRASHLOCATION + cfile); // adding crash file
			SshExecutor.writeDataToFile(config, crashentity.getMessage());

			try {
				LOGGER.log(Level.INFO, "Checking ls in dsymlocation");
				SshExecutor.executeCommand(new SshConfig(host, username, pass, "ls " + buildlocation)); // Checking the file available status
			} catch (Exception e) {
				LOGGER.log(Level.INFO, "Exception (nofile): ", e);
				copyDSymFiletoMac(crashentity, dsymfile, crashentity.getDsymPath(), mac, buildlocation,AppticsConstants.SYMBOLICATION);

				try {
					LOGGER.log(Level.INFO, "Again_inner_ls_check");
					SshExecutor.executeCommand(new SshConfig(host, username, pass, "ls " + buildlocation)); // Checking the file available status
				} catch (Exception e1) {
					LOGGER.log(Level.INFO, "No file - Inner LS Check : ", e1);
					throw new Exception("No file at Mac Server for AppversionID "+crashentity.getAppVersionID()+", AppReleaseVersionID "+crashentity.getAppReleaseVersionID());
				}
			}

			OutputStream out = new ByteArrayOutputStream();

			SshConfig config1 = new SshConfig(host, username, pass, "sh " + scriptlocation + " " + crashlocation + " " + desymlocation + " " + buildlocation); // Desymbolicating crash command
			SshExecutor.executeCommand(config1);

			SshExecutor.writeFromFileToStream(new SshConfig(host, username, pass, cfile, desymlocation + ".json", 20), out); // writing file into stream
			SshExecutor.executeCommand(new SshConfig(host, username, pass, "rm -rvf " + crashlocation)); // removing crash file

			crash = ((ByteArrayOutputStream) out).toString();

			LOGGER.log(Level.INFO, "Crashshes {0}", crash);
			SshExecutor.executeCommand(new SshConfig(host, username, pass, "rm -rvf " + desymlocation + ".json")); // removing symbolicated file

			crashdetails = new JSONObject(crash);

				if (!CommonUtil.isEmpty(crashdetails)) {

					message = crashdetails.getString("crash");
					String crash_title = crashdetails.getString("crash_title");
					String crash_type = crashdetails.getString("crash_type");

					crash_title = crash_title.trim().isEmpty()?AppticsConstants.OTHERS:crash_title;

					LOGGER.log(Level.INFO, "CrashTitle is {0}", crash_title);

					issueName = crash_title + "\n" + (CommonUtil.isEmpty(crash_type) ? "" : crash_type);

					String library = crashdetails.getString("crashed_library");
					String head = crashdetails.getString("crash_description");
					LOGGER.log(Level.INFO, "Heading for the crash {0} and library {1}", new Object[] { head, library });
				}

				if(issueName.contains(AppticsConstants.MISSINGSYMBOLS)) {
					LOGGER.log(Level.INFO, "change the issuename {0}", issueName);
					issueName = findIssueName(message,crashentity.getCrashGroupString());
				}
				LOGGER.log(Level.INFO, "IssueName is {0}", issueName);

				crashentity.setMessage(CommonUtil.maskPII(message));
				crashentity.setIssueName(CommonUtil.maskPII(issueName));

		} catch (Exception e) {
			LOGGER.log(Level.SEVERE, "Exception while processing Symbolicateion {0}",e);
			if(crashentity.getReProcess()) {
			LOGGER.log(Level.INFO,"Failed on Mac so ReProcess to Linux");
			crashentity.setReProcess(false);
			linuxSymbolication(crashentity);
			}
		}

		finally {
			CommonUtil.deleteTmpFileInAppServer(dsymfile);
		}


	//	crashentity.setMailContent(CommonUtil.maskPII(message));

	}

	public static String findIssueName(String message,String crashGroup) {

		LOGGER.log(Level.INFO, "Find Issue Name called");
		String issueName = AppticsConstants.UNSYMBOLICATED + " - " + crashGroup;

		try {
			Pattern crashedThreadPattern = Pattern.compile("Crashed Thread:\\s*(\\d+)");
			Matcher crashedThreadMatcher = crashedThreadPattern.matcher(message);

			if (crashedThreadMatcher.find()) {
				int crashedThreadNumber = Integer.parseInt(crashedThreadMatcher.group(1));

				int startIndex = message.indexOf("Thread " + crashedThreadNumber++); // store the crashed thread number for thread usage
				int endIndex = message.contains("Thread " + crashedThreadNumber) ? message.indexOf("Thread " + crashedThreadNumber) : message.indexOf("Thread State:");
				// end Index the next number of the crashed thread
				if (startIndex < endIndex) {
					String[] threadLine = message.substring(startIndex, endIndex).split("\n");

					for (String line : threadLine) {

						Pattern pattern = Pattern.compile(AppticsConstants.TRACEREGEX);
						if (!pattern.matcher(line).matches() && Character.isDigit(line.charAt(0))) {
							LOGGER.log(Level.INFO, "unsymbolicated line is {0}",line);

							line = line.replaceAll("^\\d+", "");
							return line;
						}	
					}
				}
			} else {
				return issueName;
			}
		} catch (Exception e) {
			LOGGER.log(Level.INFO, "Exception while find the issuename for missing symbols ", e);
		}
		return issueName;
	}



	public static void processNativeObfuscation(CrashEntity crashentity) throws Exception {

		String issueName = crashentity.getIssueName();
		String message = crashentity.getMessage();
		Integer caseNo = 1;

		File mappingFile = fetchFile(AppticsConstants.BUILDMAPPINGFILES, crashentity);
		InputStream crashin = null;

		try{
			if(mappingFile != null){
				crashin = new ByteArrayInputStream(crashentity.getExceptionInfo());

				ReTrace r = new ReTrace(mappingFile);
				message = r.execute(crashin);
			}
		}
		catch(Exception e){
			LOGGER.info("Exception while using retrace "+ e);
		}
		finally{

			if(crashin !=null){
				try {
					crashin.close();
				} catch (IOException e) {
					LOGGER.log(Level.INFO,"Exception while closing inputstream {0}",e);
				}
			}
			CommonUtil.deleteTmpFileInAppServer(mappingFile);
		}

		if (crashentity.getExceptionGroup().equalsIgnoreCase(AppticsConstants.ANR)) {
			caseNo = 4;
		}


		crashentity.setMessage(CommonUtil.maskPII(message));	

		String temp = retrieveAndroidUniqueException(crashentity,caseNo);
		if(!CommonUtil.isEmpty(temp) && temp.length() != 0){
			issueName = temp;
			LOGGER.log(Level.INFO, "Unique Message : {0}",issueName);

		}
		crashentity.setIssueName(CommonUtil.maskPII(issueName));

	}

	  public static String retrieveAndroidUniqueException(CrashEntity crashentity,int i) {
		 // Using old method  
	    	String uniqueMessage = "";
	    	try {
		        String[] lines = {};
		        if (CommonUtil.isEmpty(crashentity.getBundle(), crashentity.getMessage())) {
		        	return "";
		        }
		        lines = crashentity.getMessage().split("\\n");

		        String exceptionString = "Exception";
		        String causedString = "Caused by:";

		        switch (i) {
		            case 1:
		                String identifier = crashentity.getBundle();
		                if(lines[0].indexOf(exceptionString) == -1) {
		                	break;
		                }
		                String temp = lines[0].substring(0, lines[0].indexOf(exceptionString)+exceptionString.length());

		                uniqueMessage = unique(lines, identifier);
		                if(uniqueMessage.trim().equals("") && identifier.split("\\.").length > 1) {
		                    identifier = identifier.substring(0, identifier.lastIndexOf("."));
		                    uniqueMessage = unique(lines, identifier);
		                }

		                uniqueMessage = uniqueMessage != "" ? temp+" "+ uniqueMessage : uniqueMessage;
		                break;

		            case 2:
		                uniqueMessage = Arrays.stream(lines).filter(line -> line.startsWith(causedString)).reduce((l, l1) -> l1).orElse("");
		                if ("".equals(uniqueMessage)){
		                    break;
		                }
		                String temp1 = uniqueMessage;

		                StringBuilder result = new StringBuilder();

		                if(uniqueMessage.indexOf(exceptionString) == -1) {
		                	result.append(uniqueMessage.substring(uniqueMessage.indexOf(causedString)+causedString.length(), uniqueMessage.indexOf(exceptionString)+exceptionString.length()));
		                }

		                AtomicBoolean flag = new AtomicBoolean(false);
		                Arrays.stream(lines).forEach(line -> {
		                    if(flag.get()){
		                        result.append(line);
		                        flag.set(false);
		                    }
		                    if(line.equals(temp1)){
		                        flag.set(true);
		                    }
		                });

		                uniqueMessage = result.toString();
		                break;

		            case 3:
		            	if(lines[0].indexOf(exceptionString) != -1)
		            	{
		            		uniqueMessage = lines.length > 1 ? lines[0].substring(0, lines[0].indexOf(exceptionString)+exceptionString.length()) + " "+ lines[1] : uniqueMessage;
		            	}
		                break;

		            case 4:
		            	 identifier = crashentity.getBundle();
		            	 uniqueMessage = unique(lines, identifier);

		            	 if(!CommonUtil.isEmpty(uniqueMessage)) {
		            		 String tmpissue =crashentity.getIssueName();

		            		 tmpissue = (tmpissue.contains("(") && tmpissue.contains(":")?tmpissue.substring(0,tmpissue.indexOf("(")):tmpissue).trim();

		            		 uniqueMessage = tmpissue+" "+uniqueMessage;
		            	 }
		        }
		        if(uniqueMessage == "" && i <= 3) {
		            uniqueMessage = retrieveAndroidUniqueException(crashentity,i+1);
		        }
	    	}catch (Exception e) {
	    		LOGGER.log(Level.SEVERE, "Exception while fetching uniqueMessage ", e);
	    	}
	        return uniqueMessage;
	    }

		private static String unique(String[] lines, String bundle){
	        String uniqueMessage = Arrays.stream(lines).filter(line -> line.contains("at " + bundle)).findFirst().orElse("");
	        return uniqueMessage;
	    }

	public static void processReactReport(CrashEntity crashEntity) {

		try {
			String crashdetails[] = null;

			String message = crashEntity.getMessage();


			String issueName = AppticsConstants.UNSYMBOLICATED;
			// Map File Process
			LOGGER.log(Level.INFO, "Calling fetch react map file");

			String entityName = AppticsConstants.REACTANDROIDMAP;
			if (crashEntity.getPlatform().equalsIgnoreCase(AppticsConstants.IOS)) {
				entityName = AppticsConstants.REACTIOSMAP;
			}

			File symbolFile = fetchFile(AppticsConstants.REACTNATIVEFILES, crashEntity);

			File unzipFile = !CommonUtil.isEmpty(symbolFile) ? unzipFile(symbolFile, entityName) : null;

			if (!CommonUtil.isEmpty(unzipFile)) {

				String symbolicatemsg = processHybridSymbolication(crashEntity.getMessage(), unzipFile, crashEntity.getCrashType() == AppticsConstants.EXCEPTIONTYPE_FLUTTER);

				if (!CommonUtil.isEmpty(symbolicatemsg)) {
					String crash = "";

					if (symbolicatemsg.contains("stack:")) {
						symbolicatemsg = symbolicatemsg.substring(symbolicatemsg.indexOf("stack:") + 6);
					}
					crashdetails = symbolicatemsg.trim().split("\n");
					for (String crashline : crashdetails) {
						Integer index = crashline.contains("/") ? crashline.lastIndexOf("/") : 0;
						String classandline = crashline.substring(index + 1);
						crash += classandline + "\n";
					}
					crashdetails = crash.split("\n");

					if (crashdetails[0].contains(":") ? !crashdetails[0].split(":")[0].equals("null") : true) {
						message = crashEntity.getIssueName() + "\n" + crash;
						issueName = crashdetails[0];
					}
				}
			}
			crashEntity.setMessage(CommonUtil.maskPII(message));
			crashEntity.setIssueName(CommonUtil.maskPII(issueName));


		} catch (Exception e) {
			LOGGER.log(Level.INFO, "Exception While processing ReactNative Crash");
		}

	}

