			} else {
				for (UploadedFileItem fileItem : fileItems) {

					fileName = appversionid + "_" + addedTime + ".zip";

					LOGGER.log(Level.INFO, "File name of build -> {0}", fileName);
					blockID = DFSFileHandler.dfsFileUpload(fileItem, fileName, appID);
				}
			}

            Long id = 0L;

			SelectQuery sq = new SelectQueryImpl(Table.getTable(AppticsConstants.BUILDFILES));
