	public static void addApplicationReport(CrashEntity crashEntity) throws Exception {

		LOGGER.log(Level.INFO, "Calling addExceptionReport");

		Boolean isTimeCheck = true;

			Long happendat = crashEntity.getHappenedAt();
			Long eligibleTime = CommonUtil.isTimeEligible(happendat, isTimeCheck);
			if (eligibleTime == 0l) {
				LOGGER.log(Level.INFO, "Returning, because incoming date is not eligible, triggeredTime -> {0}", happendat);
