			sq.addSelectColumn(Column.getColumn(AppticsConstants.BUILDFILES, AppticsConstants.CRASHTYPE));

			Criteria criteria = new Criteria(Column.getColumn(AppticsConstants.BUILDFILES, AppticsConstants.APID), apid, QueryConstants.EQUAL).and(Column.getColumn(AppticsConstants.BUILDFILES, AppticsConstants.APPVERSIONID), appversionid, QueryConstants.EQUAL).and(Column.getColumn(AppticsConstants.BUILDFILES, AppticsConstants.APPRELEASEVERSIONID), appreleaseversionid, QueryConstants.EQUAL);
			sq.setCriteria(criteria);

			Persistence per = DBHandler.getPersistence();
			DataObject dobj = per.get(sq);

			if (dobj.containsTable(AppticsConstants.BUILDFILES)) {
				LOGGER.log(Level.INFO, "File exist");

				Row row = dobj.getFirstRow(AppticsConstants.BUILDFILES);

				row.set(AppticsConstants.DFSFILEPATH, fileName);
				row.set(AppticsConstants.BLOCKID, blockID);
				row.set(AppticsConstants.ADDEDBY, addedBy);
				row.set(AppticsConstants.ADDEDTIME, addedTime);

                id = (Long) row.get(AppticsConstants.BUILDFILEID);

				dobj.updateRow(row);
				per.update(dobj);

			} else {

				Integer type = getcrashtype(crashtype);

				Row r = new Row(AppticsConstants.BUILDFILES);
				r.set(AppticsConstants.APID, apid);
				r.set(AppticsConstants.APPVERSIONID, appversionid);
				r.set(AppticsConstants.BLOCKID, blockID);
