						LOGGER.log(Level.INFO, "Skiping unsymbolicated and Missing Symbols crash to assign in projects for {0},{1},{2},{3},{4},{5}", new Object[] { bundleId, issueName, bugDescription, uniqueId, appID, crashEntity.getAppVersionID()});
