			Persistence per = DBHandler.getPersistence();
			DataObject dobj = per.get(sq);

			if (dobj.containsTable(AppticsConstants.BUILDFILES)) {
				LOGGER.log(Level.INFO, "File exist");

				Row row = dobj.getFirstRow(AppticsConstants.BUILDFILES);

				row.set(AppticsConstants.DFSFILEPATH, fileName);
