	public static Map<Long, Boolean> getUniqueID(Long projectID, String uniqueMessage, String screenname, int mode, Long pid, String tableName, String pkCol) {
		Map<Long, Boolean> uniqueIDres = new LinkedHashMap<Long, Boolean>();

		SelectQuery sq = new SelectQueryImpl(Table.getTable(tableName));
		sq.addSelectColumn(Column.getColumn(tableName, pkCol));

		Criteria c = new Criteria(Column.getColumn(tableName, "Mode"), mode, QueryConstants.EQUAL);
		c = c.and(new Criteria(Column.getColumn(tableName, "Message"), uniqueMessage, QueryConstants.EQUAL));
		sq.setCriteria(c);

		Persistence p = DBHandler.getPersistence();
		DataObject dobj = null;

		try {
			dobj = p.get(sq);

			if (!dobj.containsTable(tableName)) {
				Row r = new Row(tableName);

				r.set(AppticsConstants.PID, pid);
				r.set(AppticsConstants.MESSAGE, uniqueMessage);
				r.set(AppticsConstants.SCREEN, screenname);
				r.set(AppticsConstants.MODE, mode);
				Long currentTime = System.currentTimeMillis();
				r.set(AppticsConstants.MAILSENDAT, currentTime); // NO I18N MailSentAt
				r.set(AppticsConstants.COUNT, 1); // NO I18N
				r.set(AppticsConstants.COUNTUPDATEDAT, currentTime); // NO I18N CountUpdatedAt

				Long uniqueID = DBHandler.insertRow(r, tableName, pkCol);
				LOGGER.log(Level.INFO, "added-uniqueID{0} : {1}", new Object[] { pkCol, uniqueID });

				uniqueIDres.put(uniqueID, true);

			} else {
				Row r = dobj.getFirstRow(tableName);
				uniqueIDres.put((Long) r.get(pkCol), false);

			}

			return uniqueIDres;
		} catch (Exception e) {
			LOGGER.info("Exception while fetching unique message id " + e);
			return uniqueIDres;
		}
	}

